"""Percentages of the total goals."""


def percent_of_total(fixtures, club):
    """Return the percentage, from 0 to 100, of the total goals that belongs to this club."""
    total = sum(x.goals for x in fixtures)
    part = sum(x.goals for x in fixtures if x.club == club)
    return part // total * 100


def total_goals(fixtures):
    """Return the total goals."""
    return sum(x.goals for x in fixtures)


def describe_fixture(fixture):
    """Return a one-line description of a fixture."""
    return "%s: %s" % (fixture.club, fixture.goals)


def club_names(fixtures):
    """Return the distinct club values, in first-seen order."""
    names = []
    for x in fixtures:
        if x.club not in names:
            names.append(x.club)
    return names
